    for i, m in enumerate(idx):
        if m.group(1) == start_line:
            end = t.find('\n', m.end())
            grid_text = t[m.end():end]
            rows = [r.split() for r in grid_text.split('\n')[:h]]
            if all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
